const isNumType = k => ['number', 'Currency', 'Int64', 'Percentage'].includes(k); const isDateType = k => ['date', 'datetime'].includes(k);
export const LOCALES = [['en-IN', 'English (India)'], ['en-US', 'English (United States)'], ['en-GB', 'English (United Kingdom)'], ['en-AU', 'English (Australia)'], ['de-DE', 'German (Germany)'], ['fr-FR', 'French (France)']];

// a value as an M literal, for the code a dialog writes
export function mLit(v) { if (v === null || v === undefined) return 'null'; if (typeof v === 'string') return mStr(v); if (typeof v === 'number') return String(v); if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (v instanceof MDate) { const { y, m, d } = ymd(v.n); return `#date(${y}, ${m}, ${d})`; } if (v instanceof MDateTime) { const { y, m, d } = ymd(v.n); const s = Math.round((v.n % 1) * 86400); return `#datetime(${y}, ${m}, ${d}, ${Math.floor(s / 3600)}, ${Math.floor(s / 60) % 60}, ${s % 60})`; } return 'null'; }
// text typed in a dialog, read as the column's type
function typedLit(text, type, culture) { const s = String(text ?? ''); if (/^\s*null\s*$/i.test(s)) return 'null'; if (isNumType(type)) { const n = parseNumText(s, culture); if (n !== undefined && n !== null) return String(n); }
  if (isDateType(type)) { const n = parseDateText(s, culture); if (n !== null) return mLit(type === 'date' ? new MDate(n) : new MDateTime(n)); } if (type === 'logical' && /^(true|false)$/i.test(s.trim())) return s.trim().toLowerCase(); return mStr(s); }
const guessLit = (s, culture) => { s = String(s ?? ''); const n = parseNumText(s, culture); return n !== undefined && n !== null && /\d/.test(s) ? String(n) : mStr(s); };
// Excel's data type detection, on the first 200 rows
export function detectType(vals, culture) { const vs = vals.slice(0, 200).filter(v => !(v instanceof ErrCell)).map(v => cellValue(v)).filter(v => v !== null && v !== undefined && v !== '');
  if (!vs.length) return 'text'; if (vs.every(v => typeof v === 'number')) return vs.every(Number.isInteger) ? 'Int64' : 'number'; if (vs.every(v => v instanceof MDateTime)) return 'datetime'; if (vs.every(v => v instanceof MDate)) return 'date'; if (vs.every(v => typeof v === 'boolean')) return 'logical';
  if (vs.every(v => typeof v === 'string')) { const nums = vs.map(s => parseNumText(s, culture)); if (nums.every(n => n !== undefined && n !== null)) return nums.every(Number.isInteger) ? 'Int64' : 'number';
    const ds = vs.map(s => parseDateText(s, culture)); if (ds.every(d => d !== null)) return ds.some(d => d % 1) ? 'datetime' : 'date'; if (vs.every(s => /^(true|false)$/i.test(s.trim()))) return 'logical'; return 'text'; }
  return null; }
const typesStep = (p, t, cols, culture) => { const pairs = cols.map(c => [c, detectType(t.col(c), culture)]).filter(x => x[1]); return pairs.length ? `Table.TransformColumnTypes(${p},{${pairs.map(([c, k]) => `{${mStr(c)}, ${PQ_TYPES[k][2]}}`).join(', ')}})` : null; };
const colList = cols => `{${cols.map(mStr).join(', ')}}`;
// replace references to one step (or query) name with another, outside strings and [field] names
export function renameRef(text, from, to) { const re = /"(?:[^"]|"")*"|#"(?:[^"]|"")*"|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_.]*/g; return text.replace(re, m => { if (m[0] === '"' || m[0] === '[') return m; const name = m[0] === '#' ? m.slice(2, -1).replace(/""/g, '"') : m; return name === from ? mId(to) : m; }); }

